insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'are-pets-allowed-in-dubai-rental-apartments', 'Are pets allowed in Dubai rental apartments?', '<p>Pet policies are owner-specific. Many buildings also have Emaar/DAMAC pet rules. Check listing amenities or <a href="/pages/contact">contact our team</a> before booking a <a href="/account/viewings">viewing requests</a>.</p>', 'Are pets allowed in Dubai rental apartments?', 17, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-rera-tenancy-contract-form-a-vs-form-b', 'What is a RERA tenancy contract Form A vs Form B?', '<p>Form A is the standard RERA unified tenancy contract used for most residential leases. Your agent generates the correct form through <a href="/account/transactions">property applications</a>. See <a href="/pages/renting-guide">Renting Guide</a> for the full process.</p>', 'What is a RERA tenancy contract Form A vs Form B?', 18, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-quickly-can-i-move-in-after-approving-a-rental', 'How quickly can I move in after approving a rental?', '<p>Typically 5–10 business days after contract signing and cheque clearance. Timeline appears in <a href="/pages/shipping">Handover Information</a>. Track status in <a href="/account/transactions">property applications</a>.</p>', 'How quickly can I move in after approving a rental?', 19, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'do-i-pay-vat-on-residential-rent-in-dubai', 'Do I pay VAT on residential rent in Dubai?', '<p>Residential rent is generally VAT-exempt. Agency fees and some admin charges may include 5% VAT — shown in your payment breakdown in <a href="/account/transactions">property applications</a>.</p>', 'Do I pay VAT on residential rent in Dubai?', 20, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-rent-a-property-without-a-uae-bank-account', 'Can I rent a property without a UAE bank account?', '<p>Some owners accept international transfers for short stays; long-term leases usually require UAE cheques or local bank transfer. <a href="/pages/contact">contact our team</a> to discuss options for your situation.</p>', 'Can I rent a property without a UAE bank account?', 21, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-district-cooling-and-who-pays-for-it', 'What is district cooling and who pays for it?', '<p>District cooling (Empower/Faruq) is separate from DEWA and billed monthly based on usage. Confirm whether chiller is landlord-paid or tenant-paid in your contract via <a href="/account/transactions">property applications</a>.</p>', 'What is district cooling and who pays for it?', 22, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-schedule-a-rental-viewing-in-dubai', 'How do I schedule a rental viewing in Dubai?', '<p>Open any listing and book a viewing online. Track confirmations in <a href="/account/viewings">viewing requests</a>. Read <a href="/pages/how-it-works">How It Works</a> for the full journey from inquiry to keys.</p>', 'How do I schedule a rental viewing in Dubai?', 23, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'where-can-i-browse-verified-rental-listings-in-dubai', 'Where can I browse verified rental listings in Dubai?', '<p>Explore <a href="/collection/rentals">holiday and long-term rentals</a>, <a href="/collection/new">new listings</a> additions, or use <a href="/search">property search</a> by area and budget. Save favourites in <a href="/account">My Account</a>.</p>', 'Where can I browse verified rental listings in Dubai?', 24, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-foreigners-buy-property-in-dubai', 'Can foreigners buy property in Dubai?', '<p>Yes — nationals of most countries can buy freehold property in designated areas. Eligibility is confirmed per listing. Start with <a href="/pages/buying-guide">Buying Guide</a> and browse <a href="/collection/sales">properties for sale</a>.</p>', 'Can foreigners buy property in Dubai?', 25, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-freehold-area-in-dubai', 'What is a freehold area in Dubai?', '<p>Freehold zones allow full foreign ownership (e.g. Dubai Marina, Downtown, JVC, Palm Jumeirah). Leasehold areas grant long-term rights only. Each <a href="/collection/sales">properties for sale</a> listing notes ownership type.</p>', 'What is a freehold area in Dubai?', 26, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-much-is-the-dld-transfer-fee-when-buying-in-dubai', 'How much is the DLD transfer fee when buying in Dubai?', '<p>Dubai Land Department (DLD) charges 4% of the sale price plus admin fees. Amounts appear in your transaction breakdown in <a href="/account/transactions">property applications</a> before payment.</p>', 'How much is the DLD transfer fee when buying in Dubai?', 27, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-an-oqood-vs-a-title-deed', 'What is an Oqood vs a title deed?', '<p>Oqood registers off-plan sales; title deed is issued after handover/completion. Your agent explains which stage applies in <a href="/account/transactions">property applications</a>. See <a href="/pages/buying-guide">Buying Guide</a> for off-plan vs ready property.</p>', 'What is an Oqood vs a title deed?', 28, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'do-i-need-a-mortgage-to-buy-property-in-dubai', 'Do I need a mortgage to buy property in Dubai?', '<p>Cash and mortgage purchases are both common. UAE residents may finance up to 80% LTV for first homes (subject to bank approval). <a href="/pages/contact">contact our team</a> for mortgage partner introductions.</p>', 'Do I need a mortgage to buy property in Dubai?', 29, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-booking-deposit-when-buying-in-dubai', 'What is a booking deposit when buying in Dubai?', '<p>A booking deposit (often 5–10%) secures the unit while SPA is prepared. It''s held per RERA escrow rules for off-plan. Details in <a href="/pages/buying-guide">Buying Guide</a> and <a href="/account/transactions">property applications</a>.</p>', 'What is a booking deposit when buying in Dubai?', 30, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-long-does-property-transfer-take-at-dld', 'How long does property transfer take at DLD?', '<p>Ready property transfers often complete in 1–3 weeks after NOC and funds clear. Off-plan follows developer handover schedules. Track milestones in <a href="/account/transactions">property applications</a>.</p>', 'How long does property transfer take at DLD?', 31, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-snagging-on-a-new-dubai-property', 'What is snagging on a new Dubai property?', '<p>Snagging is a pre-handover inspection listing defects for the developer to fix. We recommend snagging for new builds — <a href="/pages/shipping">Handover Information</a> explains the process.</p>', 'What is snagging on a new Dubai property?', 32, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-buy-off-plan-property-as-a-non-resident', 'Can I buy off-plan property as a non-resident?', '<p>Many developers sell to non-residents with passport copies and proof of funds. Payment plans vary. Browse <a href="/collection/sales">properties for sale</a> and read <a href="/pages/buying-guide">Buying Guide</a> for off-plan due diligence.</p>', 'Can I buy off-plan property as a non-resident?', 33, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-rera-escrow-for-off-plan-purchases', 'What is RERA escrow for off-plan purchases?', '<p>Buyer payments must go into RERA-approved escrow accounts for registered projects — protecting funds until construction milestones. Verified in <a href="/account/transactions">property applications</a>.</p>', 'What is RERA escrow for off-plan purchases?', 34, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'are-service-charges-included-when-buying-an-apartment', 'Are service charges included when buying an apartment?', '<p>Service charges are annual fees for building maintenance, separate from purchase price. Ask your agent for the latest SC rate on any <a href="/collection/sales">properties for sale</a> listing.</p>', 'Are service charges included when buying an apartment?', 35, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-no-objection-certificate-noc-for-resale', 'What is a No Objection Certificate (NOC) for resale?', '<p>Developers issue NOCs confirming no outstanding dues before DLD transfer. Your agent obtains NOC as part of <a href="/account/transactions">property applications</a> workflow.</p>', 'What is a No Objection Certificate (NOC) for resale?', 36, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-buy-property-in-dubai-through-a-company', 'Can I buy property in Dubai through a company?', '<p>Yes — corporate ownership is allowed with proper licensing and documentation. <a href="/pages/contact">contact our team</a> for corporate purchase requirements.</p>', 'Can I buy property in Dubai through a company?', 37, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-taxes-apply-when-buying-property-in-dubai', 'What taxes apply when buying property in Dubai?', '<p>Dubai has no annual property tax; one-time DLD 4% transfer fee applies. No capital gains tax for individuals currently. Confirm latest rules via <a href="/pages/contact">contact our team</a>.</p>', 'What taxes apply when buying property in Dubai?', 38, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-make-an-offer-on-a-dubai-property', 'How do I make an offer on a Dubai property?', '<p>Submit an inquiry on the listing with your offer terms. Your agent negotiates with the owner and updates <a href="/account/transactions">property applications</a>. Compare comps via <a href="/search">property search</a>.</p>', 'How do I make an offer on a Dubai property?', 39, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-the-difference-between-ready-and-off-plan', 'What is the difference between ready and off-plan?', '<p>Ready units are completed and transferable immediately. Off-plan is under construction with staged payments. Both appear in <a href="/collection/sales">properties for sale</a> — filter by availability.</p>', 'What is the difference between ready and off-plan?', 40, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'do-i-need-a-lawyer-when-buying-in-dubai', 'Do I need a lawyer when buying in Dubai?', '<p>Many buyers use the SPA prepared by the developer or agency; complex deals may need independent legal review. Contract review happens in <a href="/account/transactions">property applications</a> before you sign.</p>', 'Do I need a lawyer when buying in Dubai?', 41, true from public.faq_categories where slug = 'buying-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
